804	function formatResourceIds(store: Store, ids: string[]): string {
805	  return ids
806	    .map((id) => {
807	      const r = store.resources.find((x) => x.id === id);
808	      return r ? `${id}（${r.name}）` : id;
809	    })
810	    .join('、');
