833	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
834	  return mergeIntervals(
835	    r.open.map(
836	      ([s, e]) =>
837	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
838	    ),
