842	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
843	function subtractSegments(
844	  segments: Array<[number, number]>,
845	  cuts: Array<[number, number]>,
846	): Array<[number, number]> {
847	  let result = segments;
848	  for (const [cs, ce] of mergeIntervals(cuts)) {
849	    const next: Array<[number, number]> = [];
850	    for (const [s, e] of result) {
851	      if (ce <= s || e <= cs) {
852	        next.push([s, e]);
853	        continue;
854	      }
855	      if (s < cs) next.push([s, cs]);
856	      if (ce < e) next.push([ce, e]);
857	    }
858	    result = next;
859	  }
860	  return result;
861	}
