863	// 某资源的有效停用记录（按开始时间、标识排序）
864	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
865	  return store.closures
866	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
867	    .sort(
868	      (a, b) =>
869	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
870	        a.id.localeCompare(b.id),
871	    );
872	}
873	
874	// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）
875	function availableSegmentsOf(store: Store, r: ResourceRec): Array<[number, number]> {
876	  const cuts = activeClosuresOf(store, r.id).map(
877	    (c) =>
878	      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
879	  );
880	  return subtractSegments(openSegmentsOf(r), cuts);
881	}
