889	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
890	function findCoverageGaps(
891	  store: Store,
892	  ids: string[],
893	  startMin: number,
894	  endMin: number,
895	): CoverageGap[] {
896	  const gaps: CoverageGap[] = [];
897	  for (const id of ids) {
898	    const r = store.resources.find((x) => x.id === id)!;
899	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
900	    const closures = activeClosuresOf(store, id).filter((c) => {
901	      const cs = parseDateTime(c.start, '停用开始时间');
902	      const ce = parseDateTime(c.end, '停用结束时间');
903	      return cs < endMin && startMin < ce;
904	    });
905	    gaps.push({id, r, closures});
906	  }
907	  return gaps;
908	}
909	
910	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
911	function gapLines(gaps: CoverageGap[], indent: string): string[] {
912	  const lines: string[] = [];
913	  for (const g of gaps) {
914	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
915	    for (const c of g.closures) {
916	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
917	    }
918	  }
919	  return lines;
920	}
