1146	async function cmdRescheduleBooking(args: string[]): Promise<void> {
1147	  const {values, positionals} = parseFlags(args, ['start', 'end', 'resource'], ['resource']);
1148	  if (positionals.length !== 1) {
1149	    throw new UsageError('用法: reschedule-booking <预约标识> [--start ...] [--end ...] [--resource ...]');
1150	  }
1151	  const id = positionals[0];
1152	
1153	  const file = activeDataFile;
1154	  const store = await loadStore(file);
1155	  const booking = store.bookings.find((b) => b.id === id);
1156	  if (!booking) throw new BizError(`未知预约标识: ${id}`);
1157	  if (booking.status === 'cancelled') {
1158	    throw new BizError(`预约 ${id} 已取消，不能改期`);
1159	  }
1160	
1161	  const hasTime = values.has('start') || values.has('end');
1162	  const hasResource = values.has('resource');
1163	  if (!hasTime && !hasResource) {
1164	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
1165	  }
1166	
1167	  const startRaw = values.get('start')?.[0] ?? booking.start;
1168	  const endRaw = values.get('end')?.[0] ?? booking.end;
1169	  const startMin = parseDateTime(startRaw, '预约开始时间');
1170	  const endMin = parseDateTime(endRaw, '预约结束时间');
1171	  if (endMin <= startMin) {
1172	    throw new BizError(`预约结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
1173	  }
1174	
1175	  let ids: string[] = booking.resourceIds;
1176	  if (hasResource) {
1177	    const resourceArgs = values.get('resource')!;
1178	    ids = resolveResourceIds(store, resourceArgs);
1179	  }
1180	
1181	  assertOpenCoverage(store, ids, startMin, endMin);
1182	  // 改期检查排除自身
1183	  assertNoConflicts(findConflicts(store, ids, startMin, endMin, id), store);
1184	
1185	  // 全部可用后整体替换旧安排并落盘；失败则本进程内存与磁盘上的原安排都不变。
1186	  // seriesId 不随改期变化：改期后仍属原系列。
1187	  booking.start = startRaw;
1188	  booking.end = endRaw;
1189	  booking.resourceIds = ids;
1190	  await saveStore(file, store);
1191	  console.log(`已改期预约 ${id}（标识保持不变）`);
1192	  if (booking.seriesId) console.log(`  所属系列: ${booking.seriesId}（改期后仍属该系列）`);
1193	  console.log(`  时间: ${startRaw} → ${endRaw}`);
1194	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
1195	}
