1311	    const at = `第 ${idx + 1} 项（${rec.bookingId as string}）`;
1312	    let ok = true;
1313	
1314	    const firstAt = seenBooking.get(rec.bookingId as string);
1315	    if (firstAt !== undefined) {
1316	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
1317	      ok = false;
1318	    } else {
1319	      seenBooking.set(rec.bookingId as string, idx + 1);
1320	    }
1321	
1322	    const booking = store.bookings.find((b) => b.id === rec.bookingId);
1323	    if (!booking) {
1324	      problems.push(`${at} 未知预约标识: ${rec.bookingId}`);
1325	      ok = false;
1326	    } else if (booking.status === 'cancelled') {
1327	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
1328	      ok = false;
1329	    }
1330	
1331	    const rawRids = rec.resourceIds as string[];
1332	    const dupes = rawRids.filter((id, j) => rawRids.indexOf(id) !== j);
1333	    if (dupes.length > 0) problems.push(`${at} 资源重复指定: ${[...new Set(dupes)].join('、')}`);
1334	    const unknown = [...new Set(rawRids)]
1335	      .filter((id) => !store.resources.some((r) => r.id === id))
1336	      .sort();
1337	    if (unknown.length > 0) problems.push(`${at} 未知资源标识: ${unknown.join('、')}`);
1338	
1339	    let startMin = 0;
1340	    let endMin = 0;
1341	    let startParsed = false;
1342	    let endParsed = false;
1343	    try {
1344	      startMin = parseDateTime(rec.start as string, `${at} 目标开始时间`);
1345	      startParsed = true;
1346	    } catch (err) {
1347	      problems.push((err as BizError).message);
1348	    }
1349	    try {
1350	      endMin = parseDateTime(rec.end as string, `${at} 目标结束时间`);
1351	      endParsed = true;
1352	    } catch (err) {
1353	      problems.push((err as BizError).message);
1354	    }
1355	    if (startParsed && endParsed && endMin <= startMin) {
1356	      problems.push(
1357	        `${at} 目标结束时间必须晚于开始时间（开始: ${rec.start}，结束: ${rec.end}），允许跨日`,
1358	      );
1359	      ok = false;
1360	    }
1361	
1362	    if (!ok || !booking) {
1363	      planned.push(null);
1364	      return;
1365	    }
1366	    planned.push({
1367	      index: idx,
1368	      booking,
1369	      startRaw: rec.start as string,
1370	      endRaw: rec.end as string,
1371	      startMin,
1372	      endMin,
1373	      resourceIds: [...new Set(rawRids)].sort(),
1374	    });
1375	  });
1376	
1377	  if (problems.length > 0) {
1378	    throw new BizError(`改期清单 ${manifestFile} 校验失败，整批拒绝（原有安排保持不变）：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1379	  }
1380	  const targets = planned as BatchTarget[];
1381	  const batchIds = new Set(targets.map((t) => t.booking.id));
1382	
1383	  // 第二阶段：对“整批完成后”的安排做校验。
1384	  // 本批预约的旧占用一律不视为障碍（findConflicts 排除本批全部标识）；
1385	  // 障碍只来自本批之外的有效预约，以及本批各项的目标安排彼此之间。
1386	  const failures: BatchFailure[] = [];
1387	  for (const t of targets) {
1388	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
1389	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
1390	      (c) => !batchIds.has(c.booking.id),
1391	    );
1392	    const wanted = new Set(t.resourceIds);
1393	    const internal: BatchFailure['internal'] = [];
1394	    for (const o of targets) {
1395	      if (o.index === t.index) continue;
1396	      const overlap = o.startMin < t.endMin && t.startMin < o.endMin;
1397	      if (!overlap) continue;
1398	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
1399	      if (shared.length > 0) internal.push({other: o, shared});
1400	    }
1401	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1402	      failures.push({target: t, gaps, external, internal});
1403	    }
1404	  }
1405	
1406	  if (failures.length > 0) {
1407	    // 按清单顺序报告全部不满足条件的项；批内冲突在双方项中都会出现
1408	    const blocks = failures.map(({target: t, gaps, external, internal}) => {
1409	      const lines = [`第 ${t.index + 1} 项 ${t.booking.id} 目标 ${t.startRaw} → ${t.endRaw}：`];
1410	      if (gaps.length > 0) {
1411	        lines.push('  开放不足资源:');
1412	        lines.push(...gapLines(gaps, '    '));
1413	      }
1414	      if (external.length + internal.length > 0) {
1415	        lines.push('  冲突预约:');
1416	        for (const c of external) {
1417	          lines.push(
1418	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
1419	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
1420	          );
1421	        }
1422	        for (const x of internal) {
1423	          lines.push(
1424	            `    - ${x.other.booking.id}（本批第 ${x.other.index + 1} 项目标 ${x.other.startRaw} → ${x.other.endRaw}）` +
1425	              `：共同资源 ${formatResourceIds(store, x.shared)}`,
1426	          );
1427	        }
1428	      }
1429	      return lines.join('\n');
1430	    });
1431	    throw new BizError(
1432	      `批量改期失败：共 ${failures.length} 项不满足条件（按清单顺序），整批未改动：\n${blocks.join('\n')}`,
1433	    );
1434	  }
1435	
1436	  // 全部验证通过：一次性替换各项目标安排并原子落盘。
1437	  // 仅改时间与资源；标识、status、seriesId、标识计数全部不变，不创建任何预约或系列。
1438	  // 若保存失败，磁盘原文件保留；本进程亦以退出码 1 结束，不会报告成功。
1439	  // 资源集合均已按标识排序，按位比较即可
1440	  const sameArrangement = (t: BatchTarget): boolean =>
1441	    t.booking.start === t.startRaw &&
1442	    t.booking.end === t.endRaw &&
1443	    t.booking.resourceIds.length === t.resourceIds.length &&
1444	    t.booking.resourceIds.every((id, j) => id === t.resourceIds[j]);
1445	  const noChange = targets.every(sameArrangement);
1446	  if (noChange) {
1447	    // 幂等：提交的安排与现状完全一致时成功且不触碰数据文件；
1448	    // 不生成改期操作记录、不推进操作计数
1449	    console.log(
1450	      `批量改期成功：共 ${targets.length} 项，安排均与现状一致，无业务变化` +
1451	        '（标识与系列归属不变，未生成改期操作记录，数据文件与标识计数未改动）',
1452	    );
1453	    for (const t of targets) {
1454	      console.log(`第 ${t.index + 1} 项 ${t.booking.id}:`);
1455	      if (t.booking.seriesId) console.log(`  所属系列: ${t.booking.seriesId}（保持不变）`);
1456	      console.log(`  时间: ${t.startRaw} → ${t.endRaw}`);
1457	      console.log(`  资源: ${formatResourceIds(store, t.resourceIds)}`);
1458	    }
1459	    return;
1460	  }
1461	
1462	  // 至少一项有变化：在改动前抓取全部提交项的完整快照（标识、提交时系列归属、
1463	  // 改期前后时间与完整资源集合，顺序即清单顺序），生成一条“未撤销”操作记录，
1464	  // 与新安排在同一次原子保存中落盘后才报告成功；保存失败则不留记录、不推进计数。
1465	  const opItems: BatchOpItem[] = targets.map((t) => {
1466	    const item: BatchOpItem = {
1467	      bookingId: t.booking.id,
1468	      before: {
1469	        start: t.booking.start,
1470	        end: t.booking.end,
1471	        resourceIds: [...t.booking.resourceIds],
1472	      },
1473	      after: {start: t.startRaw, end: t.endRaw, resourceIds: [...t.resourceIds]},
1474	    };
1475	    if (t.booking.seriesId !== undefined) item.seriesId = t.booking.seriesId;
1476	    return item;
1477	  });
1478	  store.batchSeq += 1;
1479	  const opId = `O${String(store.batchSeq).padStart(4, '0')}`;
1480	  for (const t of targets) {
1481	    t.booking.start = t.startRaw;
1482	    t.booking.end = t.endRaw;
1483	    t.booking.resourceIds = t.resourceIds;
1484	  }
1485	  store.batchOps.push({id: opId, status: 'active', items: opItems});
1486	  await saveStore(file, store);
1487	
1488	  console.log(
1489	    `批量改期成功：操作标识 ${opId}，共 ${targets.length} 项（标识与系列归属不变，未创建预约或系列）`,
1490	  );
1491	  for (const t of targets) {
1492	    console.log(`第 ${t.index + 1} 项 ${t.booking.id}:`);
1493	    if (t.booking.seriesId) console.log(`  所属系列: ${t.booking.seriesId}（保持不变）`);
1494	    console.log(`  时间: ${t.startRaw} → ${t.endRaw}`);
1495	    console.log(`  资源: ${formatResourceIds(store, t.resourceIds)}`);
1496	  }
1497	  console.log(`本次改期已记录为 ${opId}：可用 list-batch-ops 查询，undo-batch-op ${opId} 整笔安全撤销。`);
1498	}
1499	
1500	// ---------------------------------------------------------------------------
1501	// 批量改期操作记录：查询与安全撤销
1502	// 快照只描述该次提交的前后安排；之后其他入口造成的现状变化不算损坏，
1503	// 撤销时按“当前值”与记录的改期后安排逐项核对。
1504	// ---------------------------------------------------------------------------
1505	
1506	const BATCH_OP_STATUS_LABEL: Record<BatchOpStatus, string> = {
1507	  active: '未撤销',
1508	  undone: '已撤销',
1509	};
1510	
1511	// 判断预约当前安排是否与某一快照完全一致（时间 + 完整资源集合，资源均已排序）
1512	function arrangementMatches(b: BookingRec, side: BatchOpItem['before']): boolean {
1513	  return (
1514	    b.start === side.start &&
1515	    b.end === side.end &&
1516	    b.resourceIds.length === side.resourceIds.length &&
1517	    b.resourceIds.every((id, j) => id === side.resourceIds[j])
1518	  );
1519	}
1520	
1521	// 渲染单项的前后安排（系列归属在首行给出）
1522	function renderBatchOpItem(store: Store, item: BatchOpItem, index: number, indent: string): string[] {
1523	  const lines = [
1524	    `${indent}第 ${index + 1} 项 ${item.bookingId}` +
1525	      (item.seriesId !== undefined ? `（系列 ${item.seriesId}）` : ''),
1526	  ];
1527	  lines.push(`${indent}  改期前: ${item.before.start} → ${item.before.end}`);
1528	  lines.push(`${indent}    资源: ${formatResourceIds(store, item.before.resourceIds)}`);
1529	  lines.push(`${indent}  改期后: ${item.after.start} → ${item.after.end}`);
1530	  lines.push(`${indent}    资源: ${formatResourceIds(store, item.after.resourceIds)}`);
1531	  return lines;
1532	}
1533	
1534	async function cmdListBatchOps(args: string[]): Promise<void> {
1535	  const {values, positionals} = parseFlags(args, []);
1536	  if (values.size > 0) {
1537	    throw new UsageError(
1538	      `list-batch-ops 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
1539	    );
1540	  }
1541	  if (positionals.length > 0) {
1542	    throw new UsageError(`list-batch-ops 不接受位置参数: ${positionals.join(' ')}`);
1543	  }
1544	
1545	  const store = await loadStore(activeDataFile);
1546	  if (store.batchOps.length === 0) {
1547	    console.log(
1548	      '暂无批量改期操作记录（无变化提交不建记录；可用 reschedule-batch 提交批量改期，undo-batch-op <操作标识> 撤销）。',
1549	    );
1550	    return;
1551	  }
1552	  // 记录按标识序号（即成功提交先后）加载与展示；项按提交顺序
1553	  const undone = store.batchOps.filter((o) => o.status === 'undone').length;
1554	  console.log(
1555	    `批量改期操作记录（共 ${store.batchOps.length} 条，按操作先后；未撤销 ${store.batchOps.length - undone} 条，已撤销 ${undone} 条）：`,
1556	  );
1557	  for (const op of store.batchOps) {
1558	    console.log(`- ${op.id} [${BATCH_OP_STATUS_LABEL[op.status]}]（${op.items.length} 项，按提交顺序）`);
1559	    op.items.forEach((item, i) => {
1560	      console.log(renderBatchOpItem(store, item, i, '    ').join('\n'));
1561	    });
1562	  }
1563	}
1564	
1565	// 撤销校验的单项失败信息
1566	interface UndoFailure {
1567	  item: BatchOpItem;
1568	  index: number; // 提交顺序（0 基）
1569	  gaps: CoverageGap[];
1570	  external: Conflict[]; // 与本操作涉及预约之外有效预约的冲突
1571	  internal: Array<{other: BatchOpItem; otherIndex: number; shared: string[]}>; // 与本操作其他恢复安排的冲突
1572	}
1573	
1574	async function cmdUndoBatchOp(args: string[]): Promise<void> {
1575	  const {values, positionals} = parseFlags(args, []);
1576	  if (values.size > 0) {
1577	    throw new UsageError(
1578	      `undo-batch-op 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
1579	    );
1580	  }
1581	  if (positionals.length !== 1) {
1582	    throw new UsageError('用法: undo-batch-op <批量改期操作标识>');
1583	  }
1584	  const opId = positionals[0];
1585	  if (!/^O\d{4,}$/.test(opId)) throw new BizError(`批量改期操作标识非法: ${opId}`);
1586	
1587	  const file = activeDataFile;
1588	  const store = await loadStore(file);
1589	  const op = store.batchOps.find((x) => x.id === opId);
1590	  if (!op) throw new BizError(`未知批量改期操作标识: ${opId}`);
1591	
1592	  if (op.status === 'undone') {
1593	    // 幂等：重复撤销已撤销记录成功且不触碰当前安排——即使之后又有改期
1594	    console.log(`操作 ${opId} 已是撤销状态，未做任何改动（当前安排保持不变）。`);
1595	    return;
1596	  }
1597	
1598	  // 前置一致性：全部涉及预约须仍有效，且当前时间、资源集合、系列归属与该记录的
1599	  // 改期后安排完全一致；按当前值比对，期间改动后又恢复一致仍可撤销。
1600	  // 任一不一致即整笔拒绝并列出全部不一致预约。
1601	  const mismatches: string[] = [];
1602	  const involved = new Map<string, {booking: BookingRec; item: BatchOpItem; index: number}>();
1603	  op.items.forEach((item, index) => {
1604	    const b = store.bookings.find((x) => x.id === item.bookingId);
1605	    if (!b) {
1606	      mismatches.push(`第 ${index + 1} 项 ${item.bookingId}：预约记录不存在（数据可能已损坏）`);
1607	      return;
1608	    }
1609	    if (b.status === 'cancelled') {
1610	      mismatches.push(`第 ${index + 1} 项 ${b.id}：预约已取消，撤销不能复活已取消预约`);
1611	      return;
1612	    }
1613	    involved.set(b.id, {booking: b, item, index});
1614	    const reasons: string[] = [];
1615	    if (!arrangementMatches(b, item.after)) {
1616	      reasons.push(
1617	        `当前安排（${b.start} → ${b.end}；资源 ${b.resourceIds.join('、')}）` +
1618	          `与记录改期后安排（${item.after.start} → ${item.after.end}；资源 ${item.after.resourceIds.join('、')}）不一致`,
1619	      );
1620	    }
1621	    const curSeries = b.seriesId;
1622	    const recSeries = item.seriesId;
1623	    if (curSeries !== recSeries) {
1624	      reasons.push(
1625	        `当前系列归属 ${curSeries ?? '无'} 与记录的系列归属 ${recSeries ?? '无'} 不一致`,
1626	      );
1627	    }
1628	    if (reasons.length > 0) {
1629	      mismatches.push(`第 ${index + 1} 项 ${b.id}：` + reasons.join('；'));
1630	    }
1631	  });
1632	
1633	  if (mismatches.length > 0) {
1634	    throw new BizError(
1635	      `撤销 ${opId} 被拒绝：存在 ${mismatches.length} 项涉及预约的当前状态与该记录改期后安排不一致` +
1636	        '（整笔不变，未恢复任何安排、未改变记录状态）：\n' +
1637	        mismatches.map((m) => `- ${m}`).join('\n'),
1638	    );
1639	  }
1640	
1641	  // 可行性：对“整笔恢复后”的最终安排做校验。本操作涉及预约的当前占用一律排除
1642	  // （允许互换时段）；障碍只来自本操作之外的有效预约，以及各项恢复安排彼此之间。
1643	  const involvedIds = new Set(op.items.map((it) => it.bookingId));
1644	  const failures: UndoFailure[] = [];
1645	  op.items.forEach((item, index) => {
1646	    const startMin = parseDateTime(item.before.start, '恢复开始时间');
1647	    const endMin = parseDateTime(item.before.end, '恢复结束时间');
1648	    const gaps = findCoverageGaps(store, item.before.resourceIds, startMin, endMin);
1649	    const external = findConflicts(store, item.before.resourceIds, startMin, endMin).filter(
1650	      (c) => !involvedIds.has(c.booking.id),
1651	    );
1652	    const wanted = new Set(item.before.resourceIds);
1653	    const internal: UndoFailure['internal'] = [];
1654	    op.items.forEach((other, otherIndex) => {
1655	      if (otherIndex === index) return;
1656	      const oStart = parseDateTime(other.before.start, '恢复开始时间');
1657	      const oEnd = parseDateTime(other.before.end, '恢复结束时间');
1658	      const overlap = oStart < endMin && startMin < oEnd;
1659	      if (!overlap) return;
1660	      const shared = other.before.resourceIds.filter((id) => wanted.has(id)).sort();
1661	      if (shared.length > 0) internal.push({other, otherIndex, shared});
1662	    });
1663	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1664	      failures.push({item, index, gaps, external, internal});
1665	    }
1666	  });
1667	
1668	  if (failures.length > 0) {
1669	    // 按提交顺序报告全部失败项；批内冲突在双方项中都会出现
1670	    const blocks = failures.map(({item, index, gaps, external, internal}) => {
1671	      const lines = [
1672	        `第 ${index + 1} 项 ${item.bookingId} 恢复为 ${item.before.start} → ${item.before.end}：`,
1673	      ];
1674	      if (gaps.length > 0) {
1675	        lines.push('  开放不足资源:');
1676	        lines.push(...gapLines(gaps, '    '));
1677	      }
1678	      if (external.length + internal.length > 0) {
1679	        lines.push('  冲突预约:');
1680	        for (const c of external) {
1681	          lines.push(
1682	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
1683	              `：共同资源 ${formatResourceIds(store, c.shared)}`,

