2219	// 返回裁剪到窗口内并合并后的占用区间。
2220	function flexBusySegments(
2221	  store: Store,
2222	  ids: string[],
2223	  wStart: number,
2224	  wEnd: number,
2225	): Array<[number, number]> {
2226	  const wanted = new Set(ids);
2227	  const cuts: Array<[number, number]> = [];
2228	  for (const b of store.bookings) {
2229	    if (b.status !== 'active') continue;
2230	    if (!b.resourceIds.some((id) => wanted.has(id))) continue;
2231	    const bStart = parseDateTime(b.start, '预约开始时间');
2232	    const bEnd = parseDateTime(b.end, '预约结束时间');
2233	    const a = Math.max(bStart, wStart);
2234	    const c = Math.min(bEnd, wEnd);
2235	    if (a < c) cuts.push([a, c]);
2236	  }
2237	  return mergeIntervals(cuts);
2238	}
