2246	  const wEnd = parseDateTime(w.end, '弹性窗口结束时间');
2247	  const common = commonAvailableSegments(store, w.resourceIds, wStart, wEnd);
2248	  return subtractSegments(common, flexBusySegments(store, w.resourceIds, wStart, wEnd));
