2251	async function cmdProcessWaitlist(args: string[]): Promise<void> {
2252	  const {values, positionals} = parseFlags(args, []);
2253	  if (values.size > 0) {
2254	    throw new UsageError(`process-waitlist 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
2255	  }
2256	  if (positionals.length > 0) {
2257	    throw new UsageError(`process-waitlist 不接受位置参数: ${positionals.join(' ')}`);
2258	  }
2259	
2260	  const file = activeDataFile;
2261	  const store = await loadStore(file);
2262	
2263	  // 已兑现/已取消项永不重新处理；两种候补只按共同的登记顺序遍历等待项
2264	  const waiting = store.waitlist.filter((w) => w.status === 'waiting');
2265	  if (waiting.length === 0) {
2266	    // 明确说明且不改变记录或计数（不落盘）
2267	    if (store.waitlist.length === 0) {
2268	      console.log('候补队列为空，没有可处理的候补；记录与标识计数不变。');
2269	    } else {
2270	      console.log('候补队列中没有等待中的候补（均已兑现或已取消）；记录与标识计数不变。');
2271	    }
