2277	  // 若保存失败，磁盘原文件、记录与计数均不变。
2278	  const selected: Array<{
2279	    w: WaitlistRec;
2280	    bookingId: string;
2281	    startRaw: string;
2282	    endRaw: string;
2283	    startMin: number;
2284	    endMin: number;
2285	  }> = [];
2286	  const blocked: WaitlistRec[] = [];
2287	
2288	  for (const w of waiting) {
2289	    let slot: {startMin: number; endMin: number} | null = null;
2290	
2291	    if (w.kind === 'fixed') {
2292	      // 固定项使用原时段：重查开放覆盖与冲突（store.bookings 已含本轮先选新预约）
2293	      const startMin = parseDateTime(w.start, '候补开始时间');
2294	      const endMin = parseDateTime(w.end, '候补结束时间');
2295	      const gaps = findCoverageGaps(store, w.resourceIds, startMin, endMin);
2296	      const conflicts = findConflicts(store, w.resourceIds, startMin, endMin);
2297	      if (gaps.length === 0 && conflicts.length === 0) slot = {startMin, endMin};
2298	    } else {
2299	      // 弹性项取窗口内最早可行的开始分钟，结束不超出窗口；不能拼接空隙
2300	      const duration = w.durationMinutes!;
2301	      const free = flexFreeSegments(store, w);
2302	      for (const [s, e] of free) {
2303	        if (e - s >= duration) {
2304	          slot = {startMin: s, endMin: s + duration};
2305	          break;
2306	        }
2307	      }
2308	    }
2309	
2310	    if (slot === null) {
2311	      // 受阻项等待并继续后项：不重排队列、不移动任何已选项
2312	      blocked.push(w);
