2427	async function cmdAddClosure(args: string[]): Promise<void> {
2428	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end']);
2429	  if (positionals.length > 0) throw new UsageError(`add-closure 不接受位置参数: ${positionals.join(' ')}`);
2430	
2431	  const resourceId = requireFlag(values, 'resource');
2432	  const startRaw = requireFlag(values, 'start');
2433	  const endRaw = requireFlag(values, 'end');
2434	
2435	  const file = activeDataFile;
2436	  const store = await loadStore(file);
2437	
2438	  const resource = store.resources.find((r) => r.id === resourceId);
2439	  if (!resource) throw new BizError(`未知资源标识: ${resourceId}`);
2440	
2441	  const startMin = parseDateTime(startRaw, '停用开始时间');
2442	  const endMin = parseDateTime(endRaw, '停用结束时间');
2443	  if (endMin <= startMin) {
2444	    throw new BizError(`停用结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
2445	  }
2446	
2447	  // 登记前检查该资源的全部有效预约（含系列成员与候补兑现预约；已取消不阻挡）。
2448	  // 区间左闭右开，端点相接不算重叠；有重叠即拒绝，不改期或取消任何预约。
2449	  const affected = store.bookings
2450	    .filter((b) => {
2451	      if (b.status !== 'active' || !b.resourceIds.includes(resourceId)) return false;
2452	      const bs = parseDateTime(b.start, '预约开始时间');
2453	      const be = parseDateTime(b.end, '预约结束时间');
2454	      return bs < endMin && startMin < be;
2455	    })
2456	    .sort((a, b) => a.id.localeCompare(b.id));
2457	  if (affected.length > 0) {
2458	    const lines = affected.map((b) => `- ${b.id}（${b.start} → ${b.end}）`);
2459	    throw new BizError(
2460	      `无法登记停用：资源 ${resourceId}（${resource.name}）在该区间存在有效预约` +
2461	        `（不自动改期或取消，请先处理）：\n${lines.join('\n')}`,
2462	    );
2463	  }
2464	
2465	  // 全部校验通过后才生成标识、改内存、落盘；相同内容再次登记也是另一记录
2466	  store.closureSeq += 1;
2467	  const id = `C${String(store.closureSeq).padStart(4, '0')}`;
2468	  store.closures.push({id, resourceId, start: startRaw, end: endRaw, status: 'active'});
2469	  store.closures.sort((a, b) => a.id.localeCompare(b.id));
2470	  await saveStore(file, store);
2471	  console.log(`已登记停用 ${id}`);
2472	  console.log(`  资源: ${resourceId}（${resource.name}）`);
2473	  console.log(`  时间: ${startRaw} → ${endRaw}`);
2474	  console.log('  该区间不再计入实际可用时间；取消停用请使用 cancel-closure。');
2475	}
